CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TYPE "TenantStatus" AS ENUM ('ACTIVE','SUSPENDED','DISABLED');
CREATE TYPE "IdentityStatus" AS ENUM ('ACTIVE','SUSPENDED','DISABLED');
CREATE TABLE "Tenant" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"name" TEXT NOT NULL,"status" "TenantStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Identity" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"email" TEXT NOT NULL UNIQUE,"status" "IdentityStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "TenantIdentity" ("tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE,"identityId" UUID NOT NULL REFERENCES "Identity"("id") ON DELETE CASCADE,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY ("tenantId","identityId"));
CREATE TABLE "Session" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"identityId" UUID NOT NULL REFERENCES "Identity"("id") ON DELETE CASCADE,"expiresAt" TIMESTAMPTZ NOT NULL,"revokedAt" TIMESTAMPTZ,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Role" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE,"name" TEXT NOT NULL,UNIQUE ("tenantId","name"));
CREATE TABLE "Permission" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"key" TEXT NOT NULL UNIQUE);
CREATE TABLE "RolePermission" ("roleId" UUID NOT NULL REFERENCES "Role"("id") ON DELETE CASCADE,"permissionId" UUID NOT NULL REFERENCES "Permission"("id") ON DELETE CASCADE,PRIMARY KEY ("roleId","permissionId"));
CREATE TABLE "AuditEvent" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"actorId" UUID NOT NULL,"action" TEXT NOT NULL,"resourceType" TEXT NOT NULL,"resourceId" TEXT NOT NULL,"correlationId" TEXT NOT NULL,"metadata" JSONB NOT NULL,"occurredAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "OutboxEvent" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"eventType" TEXT NOT NULL,"aggregateType" TEXT NOT NULL,"aggregateId" TEXT NOT NULL,"payload" JSONB NOT NULL,"occurredAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"publishedAt" TIMESTAMPTZ,"attempts" INTEGER NOT NULL DEFAULT 0);
CREATE INDEX "AuditEvent_tenant_time" ON "AuditEvent" ("tenantId","occurredAt");
CREATE INDEX "AuditEvent_resource" ON "AuditEvent" ("tenantId","resourceType","resourceId");
CREATE INDEX "OutboxEvent_publish" ON "OutboxEvent" ("publishedAt","occurredAt");
CREATE INDEX "OutboxEvent_tenant_time" ON "OutboxEvent" ("tenantId","occurredAt");
ALTER TABLE "Tenant" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "TenantIdentity" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Role" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "AuditEvent" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "OutboxEvent" ENABLE ROW LEVEL SECURITY;